export function siteIconUrl(value) {
  const url = new URL(value);
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) throw new Error('Invalid website URL');
  return SITE_ICONS[url.hostname] ?? SITE_ICONS[url.hostname.replace(/^www\./, '')] ?? url.origin + '/favicon.ico';
}
